from collections import Counter, deque

class Checker:
    class Node:
        __slots__ = ("val", "left", "right")

        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None

    def _build_tree(self, arr):
        if arr == [] or arr is None:
            return None
        vals = list(arr)
        if not vals or vals[0] is None:
            return None
        root = self.Node(vals[0])
        queue = deque([root])
        i = 1
        while queue and i < len(vals):
            node = queue.popleft()
            if i < len(vals):
                left_val = vals[i]
                i += 1
                if left_val is not None:
                    node.left = self.Node(left_val)
                    queue.append(node.left)
            if i < len(vals):
                right_val = vals[i]
                i += 1
                if right_val is not None:
                    node.right = self.Node(right_val)
                    queue.append(node.right)
        return root

    def findFrequentTreeSum(self, root_arr, result):
        if not isinstance(result, list):
            return False
        root = self._build_tree(root_arr)
        if root is None:
            return result == []
        sums = []

        def dfs(node):
            if node is None:
                return 0
            total = node.val + dfs(node.left) + dfs(node.right)
            sums.append(total)
            return total

        dfs(root)
        freq = Counter(sums)
        max_freq = max(freq.values())
        expected = Counter(k for k, v in freq.items() if v == max_freq)
        return Counter(result) == expected

